<script>
/* GER-1/GER-18 (12/11/2026): "Idioma e foto" abre o popup do usuário selecionado (idioma do cadastro e remover foto). */
(function () {
  var t = document.getElementById('userBatchGrid'), b = document.querySelector('[data-user-prefs]');
  if (!t || !b) return;
  function sel() { var r = t.querySelector('tbody tr.selected'); var k = r ? String(r.getAttribute('data-key') || '') : ''; return /^\d+$/.test(k) ? k : ''; }
  t.addEventListener('click', function () { setTimeout(function () { b.disabled = !sel(); }, 0); });
  b.addEventListener('click', function () {
    var k = sel(); if (!k) return;
    var url = new URL('seguranca_usuario_preferencias.php?codusuario=' + k, window.location.href).toString(), host = window.top || window;
    if (host.GreenPortalPopups && typeof host.GreenPortalPopups.transacao90 === 'function') host.GreenPortalPopups.transacao90({ titulo: 'Idioma e foto do usuário', url: url });
    else window.open(url, '_blank');
  });
}());
</script>
